export const getTextPosition = (id, step) => {
  const textLayout = {
    left: { y: 4, x: -20, anchor: 'end' },
    right: { y: 4, x: 20, anchor: 'start' },
    top: { y: -20, x: 0, anchor: 'middle' },
    bottom: { y: 30, x: 0, anchor: 'middle' },
  }

  const labelsWithSpecialPosition = {
    step1: [
      { id: 'Milius', position: 'top' },
      { id: 'Matuschek', position: 'right' },
      { id: 'Weltwoche', position: 'top' },
      { id: 'Schweizer Monat', position: 'right' },
    ],
    step2: [
      { id: 'Milius', position: 'top' },
      { id: 'Matuschek', position: 'right' },
      { id: 'Rimoldi', position: 'top' },
      { id: 'Weltwoche', position: 'top' },
      { id: 'Schweizer Monat', position: 'right' },
    ],
    step3: [
      { id: 'Milius', position: 'top' },
      { id: 'Matuschek', position: 'right' },
      { id: 'Rimoldi', position: 'top' },
      { id: 'Weltwoche', position: 'top' },
      { id: 'Schweizer Monat', position: 'right' },
      { id: 'Gut', position: 'right' },
    ],
    step4: [
      { id: 'Matuschek', position: 'top' },
      { id: 'Milius', position: 'top' },
      { id: 'Rimoldi', position: 'top' },
      { id: 'Weltwoche', position: 'top' },
      { id: 'Schweizer Monat', position: 'right' },
      { id: 'massvoll', position: 'left' },
      { id: 'Gut', position: 'right' },
    ],
    step5: [
      { id: 'Matuschek', position: 'top' },
      { id: 'Milius', position: 'top' },
      { id: 'Weltwoche', position: 'top' },
      { id: 'Schweizer Monat', position: 'right' },
      { id: 'Rimoldi', position: 'top' },
      { id: 'massvoll', position: 'left' },
      { id: 'Gut', position: 'right' },
    ],
    step6: [
      { id: 'Matuschek', position: 'top' },
      { id: 'Milius', position: 'top' },
      { id: 'Weltwoche', position: 'top' },
      { id: 'Rimoldi', position: 'top' },
      { id: 'Schweizer Monat', position: 'right' },
      { id: 'Gut', position: 'right' },
    ],
    step7: [
      { id: 'Weltwoche', position: 'top' },
      { id: 'Corona-Transition', position: 'top' },
      { id: 'Matuschek', position: 'left' },
      { id: 'Rimoldi', position: 'right' },
      { id: 'massvoll', position: 'right' },
      { id: 'Milius', position: 'top' },
      { id: 'Gut', position: 'right' },
    ],
    step8: [
      { id: 'Weltwoche', position: 'top' },
      { id: 'Corona-Transition', position: 'top' },
      { id: 'Rimoldi', position: 'right' },
      { id: 'massvoll', position: 'right' },
      { id: 'Matuschek', position: 'left' },
      { id: 'pandamned', position: 'right' },
      { id: 'Milius', position: 'right' },
      { id: 'nebelspalter', position: 'right' },
      { id: 'Gut', position: 'right' },
    ],
  }

  const position = labelsWithSpecialPosition[step].find((p) => p.id === id)
    ?.position

  return position ? textLayout[position] : textLayout['bottom']
}

